class FEMenu;

void *operator new(unsigned int size, unsigned int alignment, const char *file, int line);

class FEMenuEntry {
    char data[96];
public:
    FEMenuEntry(stringx label, FEMenu *menu, bool floating = false, Font *font = 0);
    virtual void Disable(bool disabled = true);
};

class FEMenuSystem {
