};

class FEMenu {
public:
    int center_x;
    int center_y;
    int num_entries;
    int dy;
    int half;
    int menu_num;
    bool init;
    stringx font_filename;
    color32 color;
    color32 color_high;
    color32 color_high_alt;
    float scale;
