    int max_vis_entries;
    int flags;
    FEMenuEntry *entries;
    FEMenuEntry *first_vis_entry;
    FEMenuEntry *last_vis_entry;
    FEMenuEntry *highlighted;
    FEMenuSystem *system;
    FEMenu *back;
    int back_num;
    FEMenu *submenus;
    FEMenu *active;
    FEMenu *parent;
    void *helpText;
    int helpFlags;
    FEMenu *next_sub;

    FEMenu();
    virtual ~FEMenu();
    virtual void setBack(FEMenu *menu, int submenu = 1);
    virtual void Add(FEMenuEntry *entry);
    virtual void SetHelpText(int flags);
    virtual void cons(FEMenuSystem *menu, int x, int y, color32 c, color32 ch,
                      color32 cha, float scale = 1.0f, float scale_high = 1.2f,
                      int max_vis_entries = 8, int flags = 0);
};

class PauseMenuSystem : public FEMenuSystem {
public:
    enum { PauseMenu, TimeAttackPauseMenu, TutorialPauseMenu, EndRunMenu };
};

class ReplayMenuClass : public FEMenu {
public:
    PauseMenuSystem *sys;
    int replayEvent;

    ReplayMenuClass(FEMenuSystem *m, int x, int y, color32 c, color32 ch, color32 cha);
    virtual void ReplayStart();
    virtual void ReplayEnd();
    virtual void ReplayChange(int option);
};

extern stringx ksGlobalTextArray[];

enum {
    GT_MENU_PLAY = 42,
    GT_MENU_SAVE = 43,
    HF_UP = 0x001,
    HF_DOWN = 0x002,
    HF_SELECT = 0x010,
    HF_BACK = 0x020,
    HF_RESUME = 0x040,
    FEMENU_WRAP = 0x002
};

